-- Biblioteca · ampliación con la misma fuente (BNE, CC BY 4.0), 20/10/2026:
--   · obras anónimas impresas o copiadas en 1830 o antes (en rangos de fecha
--     cuenta el último año posible): con más de 190 años desde su
--     publicación son libres en los 20 países, incluido México (100 años);
--   · autores con fecha de muerte aproximada («ca. 1806»), antes descartados.
-- Además: años de edición recalculados sin tomar el primer año de un rango
-- («entre 1801 y 1900?» ya no da 1801) y autores sin repetir.
-- Solo se insertan obras que no estén ya (por cualquiera de sus registros de
-- la BNE ni por mismo título y autor); las existentes se actualizan.

create temporary table carga_bne (title text, subtitle text, author text, genre text, year int, epocas text[],
  author_death_year smallint, external_ref text, refs text[], slug text, visor text) on commit drop;

-- 1. Actualizar las que ya están (año, épocas y autor recalculados).
update public.works w
set year = c.year, epocas = c.epocas, author = c.author
from carga_bne c
where w.external_ref = any(c.refs) and w.deleted_at is null
  and (w.year is distinct from c.year or w.epocas <> c.epocas or w.author is distinct from c.author);

-- 2. Insertar las nuevas.
with nuevas as (
  select c.* from carga_bne c
  where not exists (select 1 from public.works w where w.external_ref = any(c.refs) and w.deleted_at is null)
    and not exists (select 1 from public.works w where w.deleted_at is null
                    and lower(public.f_unaccent(w.title)) = lower(public.f_unaccent(c.title))
                    and lower(public.f_unaccent(coalesce(w.author,''))) = lower(public.f_unaccent(c.author)))
),
ins as (
     language, is_published, is_library_work, rights_status, access_type,
     source_name, source_url, license, institution_id)
  select n.title, nullif(n.subtitle,''), n.author, n.genre, n.year, n.epocas, n.author_death_year, n.external_ref,
     case when exists (select 1 from public.works w where w.slug = n.slug and w.deleted_at is null)
          then n.slug || '-' || left(md5(n.external_ref), 6) else n.slug end,
     'es', true, true, 'public_domain', 'public_download',
     'Biblioteca Digital Hispánica — Biblioteca Nacional de España', n.visor, 'CC BY 4.0 · Biblioteca Nacional de España',
     (select id from public.institutions where slug = 'biblioteca-oficial')
  from nuevas n
  returning id, external_ref
)
select ins.id, 'script', c.visor, 'Leer en la Biblioteca Nacional', true
from ins join carga_bne c on c.external_ref = ins.external_ref;
